/* @lc app=leetcode id=1861 lang=kotlin */ class Solution { fun rotateTheBox(box: Array<CharArray>): Array<CharArray> = Array(box[0].size) { CharArray(box.size) { '.' } }.apply { box.indices.forEach { r -> (box[0].size - 1 downTo 0).fold(box[0].size - 1) { empty, c -> if (box[r][c] == '*') (c - 1).also { this[c][box.size - 1 - r] = '*' } else if (box[r][c] == '#') (empty - 1).also { this[empty][box.size - 1 - r] = '#' } else empty } } } }